+                assert(g.read_guard_token.left().frac() == old_readers + 1);
+                lemma_consts_properties_value(prev_usize);
+                lemma_consts_properties_prev_next(prev_usize, next as usize);
+                assert(prev_usize & MAX_READER_MASK != 0);
+                assert((next as usize) & MAX_READER_MASK
+                    == (prev_usize & MAX_READER_MASK) - READER);
                 assume (no_max_reader_overflow(prev_usize));
+                lemma_consts_properties_value(next as usize);
+                assert((next as usize & MAX_READER_MASK) as int
+                    == MAX_READER_U64 - g.read_guard_token.left().frac()
+                        + (V_MAX_READ_RETRACT_FRACS - g.read_retract_token.frac()));
             }
         );
     }
